def calculate_a_n(N):
    a = [0] * (N + 1)
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        term1_index = a[n-1]
        term2_index = n - a[n-1]

        # Since a_k are positive integers and a_k >= 1 for k>=1, 
        # the indices are always positive and within bounds for n >= 3.
        # a[term1_index] is a_{a_{n-1}}
        # a[term2_index] is a_{n - a_{n-1}}
        a[n] = a[term1_index] + a[term2_index]

    return a

N_max = 50
sequence = calculate_a_n(N_max)
print("n:", list(range(1, N_max + 1)))
print("a_n:", sequence[1:])

def calculate_a(N):
    """Calculates the sequence a_n up to index N."""
    a = {}
    a[1] = 1
    a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # We need a_{n-1}. It must exist since n-1 < n.
        try:
            a_n_minus_1 = a[n-1]
        except KeyError:
            # Should not happen if N is large enough and sequence is defined correctly
            raise Exception(f"a_{n-1} not found for n={n}")

        # Check if the required indices are within the calculated range
        idx1 = a_n_minus_1
        idx2 = n - a_n_minus_1

        if idx1 not in a:
            raise Exception(f"Required index idx1={idx1} for a_{n} is out of bounds (N={N}).")
        if idx2 not in a:
            raise Exception(f"Required index idx2={idx2} for a_{n} is out of bounds (N={N}).")

        val1 = a[idx1]
        val2 = a[idx2]
        a[n] = val1 + val2

    return a

# Test for k up to 10 (N = 2^11 - 1 = 2047). We use N=2048 for safety.
MAX_N = 2048
a_values = calculate_a(MAX_N)

results = {}
for k in range(1, 11):
    # Target index is 2^k - 1
    idx = (1 << k) - 1
    # Expected value is 2^(k-1)
    expected = 1 << (k - 1)

    if idx in a_values:
        actual = a_values[idx]
        is_match = actual == expected
        results[k] = (idx, actual, expected, is_match)
    else:
        results[k] = (idx, None, expected, False)

print("--- Verification of Auxiliary Lemma a_{2^k - 1} = 2^{k-1} ---")
for k, res in results.items():
    idx, actual, expected, is_match = res
    print(f"k={k}: Index = {idx} (2^{k}-1). Actual: {actual}, Expected: {expected}. Match: {is_match}")

def solve_sequence(N):
    a = {}
    for n in range(1, N + 1):
        if n == 1 or n == 2:
            a[n] = 1
        else:
            # Recurrence: a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
            if n - 1 not in a:
                # Should not happen if iterating sequentially
                return f"Error: a_{n-1} not calculated"

            a_n_minus_1 = a[n - 1]

            if a_n_minus_1 not in a:
                return f"Error: a_{a_n_minus_1} not calculated for n={n}"

            a_a_n_minus_1 = a[a_n_minus_1]

            index2 = n - a_n_minus_1
            if index2 <= 0:
                return f"Error: Index 2 ({index2}) is non-positive for n={n}"
            if index2 not in a:
                 return f"Error: a_{index2} not calculated for n={n}"

            a_n_minus_a_n_minus_1 = a[index2]

            a[n] = a_a_n_minus_1 + a_n_minus_a_n_minus_1
    return a

# Calculate up to 128, specifically checking a_62 (k=6, 2^6 - 2)
N_check = 128
sequence = solve_sequence(N_check)

# Print required values for verification
print(f"a_62: {sequence.get(62)}")
print(f"a_63: {sequence.get(63)}")
print(f"a_31: {sequence.get(31)}")
